// ─────────────────────────────────────────────────────────────────────────────
// gt-styles.ts  —  KA.SHA GT Design Style System
// Auto-generated — do not edit the GT_BASE_TEXTURES block manually.
//
// HOW IT WORKS:
//   1. Each GT style has a pre-rendered 1024×1024 base texture (PNG, base64).
//   2. applyGtStyle() loads that texture onto the Fabric canvas as a background
//      image covering the full 1024×1024 area — it aligns perfectly with the
//      UV zones automatically.
//   3. recolorGtStyle() does a pixel-swap: replaces the default primary/accent
//      RGB values with the customer's chosen colors, then reloads the texture.
//   4. clearGtStyle() removes the background texture.
//   5. ALL other canvas objects (text, logos, pattern prints) sit ON TOP and
//      are never touched by the GT system.
//
// USAGE in ModelViewerCustomizer.tsx:
//   import { GT_STYLES, applyGtStyle, recolorGtStyle, clearGtStyle } from "./gt-styles";
// ─────────────────────────────────────────────────────────────────────────────
