// ─────────────────────────────────────────────────────────────────────────────
// ENGINE
// ─────────────────────────────────────────────────────────────────────────────

const GT_BG_TAG = "__kashaGtBg__";

function hexToRgb(hex: string): [number,number,number] {
  const h = hex.replace("#","");
  return [
    parseInt(h.slice(0,2),16),
    parseInt(h.slice(2,4),16),
    parseInt(h.slice(4,6),16),
  ];
}

function colorDistance(a:[number,number,number], b:[number,number,number]): number {
  return Math.abs(a[0]-b[0]) + Math.abs(a[1]-b[1]) + Math.abs(a[2]-b[2]);
}

/**
 * Pixel-swap recoloring.
 * Loads the base PNG into an offscreen canvas, walks every pixel,
 * and replaces exact-match colors with the customer's chosen colors.
 * Returns a new data-URL.
 */
async function recolorTexture(
  baseDataUrl: string,
  oldColors:   GtColors,
  newColors:   GtColors,
): Promise<string> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const canvas  = document.createElement("canvas");
      canvas.width  = 1024;
      canvas.height = 1024;
      const ctx = canvas.getContext("2d")!;
      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, 1024, 1024);
      const data = imageData.data;

      const oldP = hexToRgb(oldColors.primary);
      const oldA = hexToRgb(oldColors.accent);
      const oldT = oldColors.tertiary ? hexToRgb(oldColors.tertiary) : null;

      const newP = hexToRgb(newColors.primary);
      const newA = hexToRgb(newColors.accent);
      const newT = newColors.tertiary ? hexToRgb(newColors.tertiary) : null;

      // White background (255,255,255) — skip
      for (let i = 0; i < data.length; i += 4) {
        const r = data[i], g = data[i+1], b = data[i+2];
        const px: [number,number,number] = [r,g,b];

        if (colorDistance(px, oldP) < 8) {
          data[i]=newP[0]; data[i+1]=newP[1]; data[i+2]=newP[2];
        } else if (colorDistance(px, oldA) < 8) {
          data[i]=newA[0]; data[i+1]=newA[1]; data[i+2]=newA[2];
        } else if (oldT && newT && colorDistance(px, oldT) < 8) {
          data[i]=newT[0]; data[i+1]=newT[1]; data[i+2]=newT[2];
        }
      }

      ctx.putImageData(imageData, 0, 0);
      resolve(canvas.toDataURL("image/png"));
    };
    img.onerror = reject;
    img.src = baseDataUrl;
  });
}

/** Remove the GT background image from the canvas */
export function clearGtStyle(fc: fabric.Canvas): void {
  const toRemove = fc.getObjects().filter(
    (o) => (o as any).data?.tag === GT_BG_TAG
  );
  toRemove.forEach((o) => fc.remove(o));
}

/** Apply a GT style to the Fabric canvas at the correct UV position */
export async function applyGtStyle(
  fc: fabric.Canvas,
  style: GtStyleDef,
  customColors?: Partial<GtColors>,
): Promise<void> {
  const colors: GtColors = {
    ...style.defaultColors,
    ...customColors,
  };

  // Get base texture
  const baseUrl = GT_BASE_TEXTURES[style.id];
  if (!baseUrl) return;

  // Recolor if needed
  let textureUrl = baseUrl;
  const needsRecolor =
    (customColors?.primary  && customColors.primary  !== style.defaultColors.primary)  ||
    (customColors?.accent   && customColors.accent   !== style.defaultColors.accent)   ||
    (customColors?.tertiary && customColors.tertiary !== style.defaultColors.tertiary);

  if (needsRecolor) {
    textureUrl = await recolorTexture(baseUrl, style.defaultColors, colors);
  }

  // Remove existing GT layer
  clearGtStyle(fc);

  // Load as Fabric image covering the full 1024×1024 canvas
  const img = await fabric.FabricImage.fromURL(textureUrl, { crossOrigin: "anonymous" });

  img.set({
    left:      0,
    top:       0,
    width:     1024,
    height:    1024,
    scaleX:    1,
    scaleY:    1,
    originX:   "left",
    originY:   "top",
    selectable: false,
    evented:    false,
    data:       { tag: GT_BG_TAG, styleId: style.id },
  } as any);

  // Insert at the BACK so text/logos stay on top
  fc.add(img);
  fc.sendObjectToBack(img);
  fc.renderAll();
}

/** Change colors of the currently-applied GT style */
export async function recolorGtStyle(
  fc: fabric.Canvas,
  style: GtStyleDef,
  newColors: Partial<GtColors>,
  syncTexture: () => void,
): Promise<void> {
  await applyGtStyle(fc, style, newColors);
  syncTexture();
}